import React from "react";
import {Box, Typography, LinearProgress} from "@mui/material";
import {styled, keyframes} from "@mui/material/styles";

// انیمیشن روان بدون لگ
const wave = keyframes`
    0% {
        background-position: 0% 50%;
    }
    50% {
        background-position: 100% 50%;
    }
    100% {
        background-position: 0% 50%;
    }
`;
const StyledLinearProgress = styled(LinearProgress)(() => ({
    height: 24,
    borderRadius: 12,
    backgroundColor: "#8a8a8a",
    overflow: "hidden",
    "& .MuiLinearProgress-bar": {
        backgroundImage: `linear-gradient(
            to right,
            #750202,
            #5301a2,
            #750202,
            #5301a2,
            #750202,
            #5301a2,
            #750202
        )`,
        backgroundSize: "550% 100%",
        animation: `${wave} 8s ease-in-out infinite`,
        transition: "width 0.4s ease-in-out",
    },
}));

const LinearProgressWithSmoothGradient = ({value, label}) => {
    return (
        <Box sx={{
            width: "100%",
            mb: 1,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",

        }}>
            {/* لیبل سمت چپ */}
            <Typography sx={{
                minWidth: 100,
                fontSize: '2rem',
                fontFamily: "Bebas Neue",
            }}>{label}</Typography>

            {/* نوار پیشرفت */}
            <Box sx={{flexGrow: 1,mx:1, position: "relative"}}>
                <StyledLinearProgress variant="determinate"
                                      value={value}/>
                {/* درصد داخل نوار */}
                <Typography
                    variant="body2"
                    sx={{
                        position: "absolute",
                        top: "50%",
                        left: "50%",
                        transform: "translate(-50%, -50%)",
                        color: "white",
                        fontWeight: "bold",
                        textShadow: "1px 1px 3px rgba(0,0,0,0.6)",

                    }}
                >
                    {value}%
                </Typography>
            </Box>
        </Box>
    );
};

export default LinearProgressWithSmoothGradient;
