import {
    Box, Divider, Grid, Typography,
} from "@mui/material";
import {AboutUsHeader, Skils, Description, Scroll} from "./aboutMe/";

const AboutMe = () => {


    return (<>
        <Grid container spacing={2}
              sx={{
                  justifyContent: "space-around",
                  overflowY: 'scroll',
                  height: '100vh',
                  backgroundColor: "#252525"
              }}>
            <Grid size={12}>
                <Box sx={{
                    textAlign: "center",
                    display: "flex",
                    justifyContent: "center",
                    alignContent: "center",
                }}>
                    <Typography
                        sx={{
                            opacity: 0.1,
                            textAlign: "center",
                            position: "absolute",
                            fontSize: '7rem',
                            fontWeight: 'bold',
                            background: 'linear-gradient(to right, #b4b4b4, #4B4B4BFF, #b4b4b4)',
                            backgroundSize: '200% auto',
                            backgroundClip: 'text',
                            WebkitBackgroundClip: 'text',
                            color: 'transparent',
                            zIndex: 1,
                            WebkitTextFillColor: 'transparent',
                            animation: 'wave 4s linear' + ' infinite',
                            '@keyframes wave': {
                                '0%': {
                                    backgroundPosition: '200% center',
                                }, '100%': {
                                    backgroundPosition: '0% center',
                                },
                            },
                        }}
                    >
                        About Me
                    </Typography>
                    {/*Header*/}
                    <AboutUsHeader/>
                </Box>
                <Divider
                    sx={{
                        marginTop: "4rem", color: "#ffffff"
                    }}/>

                {/*discription Card*/}
                <Description/>

                {/*Scroll*/}
                <Scroll/>

                {/*Skils*/}
                <Skils/>
            </Grid>
        </Grid>
    </>)
}

export default AboutMe;