// AboutMe.js
import React from 'react';
import { Container, Typography, Box, List, ListItem, ListItemText, Paper } from '@mui/material';

const AboutMe = () => {
    return (
        <Container maxWidth="md">
            <Paper elevation={3} sx={{ p: 4, mt: 4 }}>
                <Typography variant="h4" gutterBottom>درباره من</Typography>
                <Typography variant="body1" paragraph>
                    سلام! من حسین نکویی هستم، علاقه‌مند به طراحی وب و برنامه‌نویسی فرانت‌اند.
                    دوره‌های HTML، CSS، Bootstrap، React و MUI رو گذروندم و علاقه زیادی به ساختن رابط‌های کاربری تمیز و حرفه‌ای دارم.
                </Typography>
                <Typography variant="body1" paragraph>
                    الان دارم پروژه‌های شخصی می‌سازم تا مهارتم قوی‌تر بشه و دنبال فرصتی برای ورود به بازار کار هستم.
                </Typography>

                <Typography variant="h6" sx={{ mt: 3 }}>مهارت‌ها</Typography>
                <List>
                    <ListItem><ListItemText primary="HTML / CSS / Sass" /></ListItem>
                    <ListItem><ListItemText primary="Bootstrap / MUI" /></ListItem>
                    <ListItem><ListItemText primary="JavaScript / React" /></ListItem>
                    <ListItem><ListItemText primary="Git / GitHub" /></ListItem>
                </List>
            </Paper>
        </Container>
    );
};

export default AboutMe;
